#chat-button:hover {
  background: #faeb50;
  color: #000000;
  transform: scale(1.05);
  transition: all 0.3s ease;
}



var chatWindow = null;
var isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);

document.getElementById('chat-button').onclick = function() {
  if (isMobile) {
    // For mobile: open in new tab with proper URL
    window.open('https://loosefmchat.chatango.com', '_blank');
  } else {
    // For desktop: try popup, fallback to new tab if blocked
    if (!chatWindow || chatWindow.closed) {
